require_once __DIR__.'/../config.php'; atlas_require_authenticated(); $i=atlas_current_identity(); if(($i['source']??'')!=='local') {header('Location: /atlas_install/');exit;} $error='';$message='';
if(session_status()!==PHP_SESSION_ACTIVE){session_name('ATLASPW');session_start(['cookie_secure'=>true,'cookie_httponly'=>true,'cookie_samesite'=>'Strict']);} if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!hash_equals((string)$_SESSION['csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Richiesta non valida.');$p=(string)($_POST['password']??'');$p2=(string)($_POST['password2']??'');if(strlen($p)<12)throw new RuntimeException('La nuova password deve contenere almeno 12 caratteri.');if(!hash_equals($p,$p2))throw new RuntimeException('Le password non coincidono.');$h=password_hash($p,PASSWORD_DEFAULT);$db=atlas_local_db();$st=$db->prepare('UPDATE atlas_local_user SET password_hash=?,must_change_password=0 WHERE id=?');$uid=(int)$i['id'];$st->bind_param('si',$h,$uid);$st->execute();atlas_auth_log('local_password_changed',['user_id'=>$uid]);$message='Password modificata.';}catch(Throwable $e){$error=$e->getMessage();}}
